import {validSnapshot,validStock,validGear} from './inventory.js';
// One host and one guest, using manual, non-trickle WebRTC signaling.
export function setupMultiplayer(game) {
  let pc=null, channel=null, role='solo', ready=false, beforeJoin=null, snapshot='', snapshotPending=false, serial=Promise.resolve(), positionTimer=null, generation=0;
  const panel=document.createElement('div'); panel.id='multiPanel'; panel.className='multi-panel hidden';
  panel.innerHTML=`<section class="multi-card" role="dialog" aria-modal="true" aria-labelledby="multiTitle"><header><h2 id="multiTitle">ふたりであそぶ</h2><button id="multiClose" class="multi-x" aria-label="閉じる">×</button></header><p>同じWi-Fiにつないだ2台で遊べます。コードは相手にだけ渡してね。</p><div id="multiStatus" role="status">はじめる人を選んでね</div><div class="multi-actions"><button id="hostBtn">ホストになる</button><button id="guestBtn">参加する</button><button id="leaveBtn" class="hidden">接続を終了</button></div><div id="steps" class="hidden"><p id="stepHelp"></p><label id="outputLabel" for="outCode">自分のコード</label><textarea id="outCode" readonly spellcheck="false" placeholder="コードを準備しています"></textarea><button id="copyCode">コードをコピー</button><label id="inputLabel" for="inCode">相手のコード</label><textarea id="inCode" spellcheck="false" placeholder="ここに貼り付けてね"></textarea><button id="acceptCode">コードを決定</button></div><p class="multi-note">コードには接続情報が含まれます。接続できない場合は、同じWi-Fiか確認してください。学校などのネットワークでは端末間通信が禁止されていることがあります。</p></section>`;
  document.body.append(panel);const $=id=>panel.querySelector('#'+id), status=t=>{$('multiStatus').textContent=t};
  let openButton=document.createElement('button');openButton.className='tool';openButton.textContent='ふたりで';openButton.id='multiplayer';document.querySelector('.topright').prepend(openButton);
  openButton.onclick=()=>{if(document.pointerLockElement)document.exitPointerLock();game.pause();panel.classList.remove('hidden')};$('multiClose').onclick=()=>panel.classList.add('hidden');
  function send(obj){if(!channel||channel.readyState!=='open')return Promise.resolve(false);const dc=channel, token=generation;serial=serial.then(async()=>{if(token!==generation||dc.readyState!=='open')return false;while(dc.bufferedAmount>256000){await new Promise(resolve=>setTimeout(resolve,20));if(token!==generation||dc.readyState!=='open')return false}dc.send(JSON.stringify(obj));return true}).catch(()=>false);return serial}
  function encode(desc){return JSON.stringify({v:4,type:desc.type,sdp:desc.sdp})}
  function decode(text,type){let d;try{d=JSON.parse(text.trim())}catch{throw Error('コードを読み取れません。全部コピーして貼り付けてね。')}if(d.v!==4)throw Error('両方の画面を更新してから、もう一度コードを作ってね。');if(d.type!==type||typeof d.sdp!=='string'||d.sdp.length>100000)throw Error(type==='offer'?'招待コードを入力してね。':'返答コードを入力してね。');return {type:d.type,sdp:d.sdp}}
  function gathered(peer){return new Promise((resolve,reject)=>{if(peer.iceGatheringState==='complete')return resolve();let timer=setTimeout(()=>{peer.removeEventListener('icegatheringstatechange',check);reject(Error('接続情報を準備できませんでした。もう一度試してね。'))},15000);function check(){if(peer.iceGatheringState==='complete'){clearTimeout(timer);peer.removeEventListener('icegatheringstatechange',check);resolve()}}peer.addEventListener('icegatheringstatechange',check)})}
  function resetUi(){ $('hostBtn').classList.remove('hidden');$('guestBtn').classList.remove('hidden');$('leaveBtn').classList.add('hidden');$('steps').classList.add('hidden');$('outCode').value='';$('inCode').value='';$('acceptCode').disabled=false; }
  function end(text,notify=true){let oldRole=role;generation++;ready=false;snapshotPending=false;clearInterval(positionTimer);positionTimer=null;const oldChannel=channel,oldPc=pc;channel=null;pc=null;role='solo';if(oldChannel){oldChannel.onclose=null;oldChannel.onmessage=null;oldChannel.close()}if(oldPc){oldPc.onconnectionstatechange=null;oldPc.close()}if(oldRole==='guest'&&beforeJoin){game.replaceSnapshot(beforeJoin);beforeJoin=null}game.removePeer();game.setMode('solo');resetUi();status(text||'接続が終了しました');if(notify&&oldRole!=='solo'){game.pause();panel.classList.remove('hidden');game.notice(text||'接続が終了しました')}}
  function newPeer(){const peer=new RTCPeerConnection({iceServers:[]});pc=peer;peer.onconnectionstatechange=()=>{if(pc!==peer)return;if(peer.connectionState==='failed'||peer.connectionState==='closed')end('接続が終了しました。もう一度やり直してね。');};return peer}
  function setupChannel(dc){channel=dc;dc.onopen=()=>{if(channel!==dc)return;status('接続しました。ワールドを準備しています…');if(role==='host')sendSnapshot();positionTimer=setInterval(()=>{if(ready){send({t:'pos',p:game.position()});if(role==='host'&&game.mobState)send({t:'mob-state',state:game.mobState()})}},150)};dc.onclose=()=>{if(channel===dc)end(role==='guest'?'ホストとの接続が切れたため、部屋を終了しました。':'参加者との接続が切れました。')};dc.onerror=()=>{if(channel===dc)end('通信できませんでした。もう一度試してね。')};dc.onmessage=e=>{try{receive(JSON.parse(e.data))}catch(err){console.error(err);end('データを読み取れませんでした。')}}}
  async function sendSnapshot(){const token=generation;snapshotPending=true;const str=JSON.stringify(game.getSnapshot());await send({t:'snapshot-start'});for(let i=0;i<str.length;i+=12000){if(token!==generation)return;await send({t:'snapshot-part',data:str.slice(i,i+12000)})}await send({t:'snapshot-end'});if(token!==generation)return;snapshotPending=false;ready=true;game.setMode('host');status('接続中：友達と建築できます');game.notice('友達が参加しました');$('steps').classList.add('hidden')}
  function validChange(m){return typeof m.k==='string'&&/^-?\d{1,3},-?\d{1,3},-?\d{1,3}$/.test(m.k)&&(m.value===null||Number.isInteger(m.value)&&m.value>=0&&m.value<8)}
  function receive(m){if(!m||typeof m.t!=='string')return;if(role==='guest'&&m.t==='snapshot-start'){snapshot='';return}if(role==='guest'&&m.t==='snapshot-part'&&typeof m.data==='string'){snapshot+=m.data;if(snapshot.length>3000000)throw Error('snapshot too large');return}if(role==='guest'&&m.t==='snapshot-end'){const state=JSON.parse(snapshot);if(!validSnapshot(state))throw Error('invalid snapshot');game.replaceSnapshot(state);snapshot='';ready=true;game.setMode('guest');status('接続中：友達と建築できます');game.notice('ワールドに参加しました');$('steps').classList.add('hidden');return}if(m.t==='craft-request'&&role==='host'&&ready&&typeof m.id==='string'){if(game.craft(m.id))send({t:'craft-commit',id:m.id,stock:game.getStock(),gear:game.getGear()});else send({t:'craft-rejected'});return}if(m.t==='craft-commit'&&role==='guest'&&ready&&validStock(m.stock)&&validGear(m.gear)){game.applyCraftStock(m.stock,m.gear,m.id);return}if(m.t==='equip-request'&&role==='host'&&ready&&typeof m.id==='string'){if(game.equip(m.id))send({t:'equip-commit',gear:game.getGear()});return}if(m.t==='equip-commit'&&role==='guest'&&ready&&validGear(m.gear)){game.applyGear(m.gear);return}if(m.t==='craft-rejected'&&role==='guest'&&ready){game.craftRejected();return}if(m.t==='mob-state'&&role==='guest'&&ready&&game.applyMobState){game.applyMobState(m.state);return}if(m.t==='mob-hit'&&role==='host'&&ready&&game.hitMobFromPeer){game.hitMobFromPeer();return}if(m.t==='pos'&&ready&&Array.isArray(m.p)&&m.p.length===3&&m.p.every(n=>Number.isFinite(n)&&Math.abs(n)<1000)){game.peerPosition(m.p);return}if(m.t==='change'&&validChange(m)){if(role==='host'&&ready){if(game.applyChange(m.k,m.value))send({t:'commit',k:m.k,value:m.value,stock:game.getStock()});else send({t:'rejected'})}return}if(m.t==='rejected'&&role==='guest'&&ready){game.notice('置けないか、ストックが足りません');return}if(m.t==='commit'&&role==='guest'&&ready&&validChange(m)&&validStock(m.stock))game.applyRemoteChange(m.k,m.value,m.stock)}
  async function host(){end('',false);role='host';game.setMode('connecting');resetUi();$('hostBtn').classList.add('hidden');$('guestBtn').classList.add('hidden');$('leaveBtn').classList.remove('hidden');$('steps').classList.remove('hidden');$('stepHelp').textContent='① 招待コードを友達に渡し、② 友達の返答コードを下に貼り付けてね。';$('outputLabel').textContent='① 招待コード';$('inputLabel').textContent='② 友達の返答コード';$('acceptCode').disabled=true;status('招待コードを作っています…');try{const peer=newPeer();setupChannel(peer.createDataChannel('blockfield',{ordered:true}));await peer.setLocalDescription(await peer.createOffer());await gathered(peer);if(pc!==peer)return;$('outCode').value=encode(peer.localDescription);$('acceptCode').disabled=false;status('招待コードを友達に渡してね')}catch(e){end(e.message)}}
  async function guest(){end('',false);role='guest';beforeJoin=game.getSnapshot();game.setMode('connecting');resetUi();$('hostBtn').classList.add('hidden');$('guestBtn').classList.add('hidden');$('leaveBtn').classList.remove('hidden');$('steps').classList.remove('hidden');$('stepHelp').textContent='① ホストの招待コードを下に貼り付け、② 作られた返答コードをホストに渡してね。';$('outputLabel').textContent='② ホストに渡す返答コード';$('inputLabel').textContent='① ホストの招待コード';status('ホストの招待コードを入力してね');try{const peer=newPeer();peer.ondatachannel=e=>setupChannel(e.channel)}catch(e){end(e.message)}}
  $('hostBtn').onclick=host;$('guestBtn').onclick=guest;$('leaveBtn').onclick=()=>end('接続を終了しました');$('acceptCode').onclick=async()=>{if(!pc)return;const peer=pc;try{$('acceptCode').disabled=true;if(role==='host'){await peer.setRemoteDescription(decode($('inCode').value,'answer'));status('友達との接続を待っています…')}else if(role==='guest'){await peer.setRemoteDescription(decode($('inCode').value,'offer'));await peer.setLocalDescription(await peer.createAnswer());await gathered(peer);if(pc!==peer)return;$('outCode').value=encode(peer.localDescription);status('返答コードをホストに渡してね')} }catch(e){status(e.message);$('acceptCode').disabled=false}};
  $('copyCode').onclick=async()=>{if(!$('outCode').value)return;try{await navigator.clipboard.writeText($('outCode').value);status('コピーしました')}catch{$('outCode').focus();$('outCode').select();status('コードを選択しました。コピーしてね')}};
  window.addEventListener('pagehide',()=>{if(role==='host')game.save();if(channel)channel.close();if(pc)pc.close()});
  return {edit(k,value){if(role==='solo'){game.applyChange(k,value);return}if(role==='host'&&ready&&!snapshotPending){if(game.applyChange(k,value))send({t:'commit',k,value,stock:game.getStock()});return}if(role==='guest'&&ready){send({t:'change',k,value});return}game.notice('接続の準備中です')},isGuest(){return role==='guest'},isActive(){return role!=='solo'},getRole(){return role},craft(id){if(role==='solo'){game.craft(id);return}if(role==='host'&&ready&&!snapshotPending){if(game.craft(id))send({t:'craft-commit',id,stock:game.getStock(),gear:game.getGear()});return}if(role==='guest'&&ready){send({t:'craft-request',id});return}game.notice('接続の準備中です')},equip(id){if(role==='solo'){game.equip(id);return}if(role==='host'&&ready&&!snapshotPending){if(game.equip(id))send({t:'equip-commit',gear:game.getGear()});return}if(role==='guest'&&ready){send({t:'equip-request',id});return}game.notice('接続の準備中です')},hitMob(){if(role==='guest'&&ready)send({t:'mob-hit'})},broadcastMob(){if(role==='host'&&ready&&game.mobState)send({t:'mob-state',state:game.mobState()})}};
}
